-- Insert Quiz Questions for Lesson: Test, Send, and Complete the Document

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 14 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 14 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'test-send-complete-document' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson test-send-complete-document not found in module 14';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should a new template be sent to a test contact first?', 
    '["It finds mistakes before real client information or terms are sent","It automatically saves the template to the library","It is required by LeadProspectrr terms of service","It sends a copy to the support team"]'::jsonb,
    'It finds mistakes before real client information or terms are sent',
    'Testing with a test contact finds mistakes before real client information or terms are sent, protecting your business reputation.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When is ''Create as Draft'' useful?', 
    '["When you want to send immediately without review","When a person must review or approve the document before sending","When the document has no fillable fields","When sending to multiple recipients at once"]'::jsonb,
    'When a person must review or approve the document before sending',
    'Create as Draft is useful when a team member must review client details and terms before the document goes out.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Does the signer need a LeadProspectrr login to complete the document?', 
    '["Yes, they must create a LeadProspectrr account first","No, the signer uses the secure link","Only if the document contains payment fields","Yes, but they can use a simplified guest account"]'::jsonb,
    'No, the signer uses the secure link',
    'The signer does not need a LeadProspectrr login. They receive a secure link and complete the document through that link.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
